package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

// generatedHeader is the standard first line in every generated file.
// writeTemplate replaces it with a server-stamped version automatically.
const generatedHeader = "// Code generated by scripts/dbcdata. DO NOT EDIT."

func writeTemplate(path string, tmpl *template.Template, data any, server ...string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}

	f, err := os.Create(path)
	if err != nil {
		return err
	}
	//nolint:errcheck
	defer f.Close()

	// Execute template into a buffer so we can stamp the server name.
	var buf strings.Builder
	if err := tmpl.Execute(&buf, data); err != nil {
		return err
	}

	out := buf.String()
	if len(server) > 0 && server[0] != "" {
		stamped := fmt.Sprintf("// Code generated by scripts/dbcdata (server: %s). DO NOT EDIT.", server[0])
		out = strings.Replace(out, generatedHeader, stamped, 1)
	}

	_, err = f.WriteString(out)
	return err
}
